namespace {
struct Checks {std::ofstream stream;std::size_t count{};explicit Checks(const std::filesystem::path& p):stream(p){stream<<std::setprecision(17)<<"name,error,tolerance,passed\n";}void operator()(std::string key,double error,double tol){++count;bool pass=std::isfinite(error)&&error<=tol;stream<<key<<','<<error<<','<<tol<<','<<pass<<'\n';if(!pass)throw std::runtime_error(key+": "+std::to_string(error));}};
double matrix_error(Mat<2,2> a,Mat<2,2> b){return std::max(norm(a[0]-b[0]),norm(a[1]-b[1]));}
Mat<2,2> hessian(const System<3,2>& sys,Vec<2> x){Mat<2,2> H{};for(int j=0;j<2;++j){Vec<2> e{};e[j]=1.;auto col=sys.hessian_vector(x,e);for(int i=0;i<2;++i)H[i][j]=col[i];}return H;}
void optional(std::ostream& s,std::optional<double> time){if(time)s<<*time;}
}
int main(int argc,char** argv){try{
 std::filesystem::path out=argc>1?argv[1]:"results/electrothermal";std::filesystem::create_directories(out);Checks check(out/"checks.csv");std::ofstream summary(out/"summary.csv");summary<<std::setprecision(17)<<"quantity,value\n";auto report=[&](std::string key,double value){summary<<key<<','<<value<<'\n';std::cout<<std::setprecision(12)<<key<<": "<<value<<'\n';};
 auto analytical=analytical_fit({1.1,.6});auto reverse=analytical_fit({-1.1,-.6});report("analytical_positive_v0",analytical[0]);report("analytical_positive_i0",analytical[1]);check("analytical equal-cost polarity branches",norm(analytical+reverse),1e-10);check("exact initial temperature rise",std::abs(exact(0.,truth)[2]),1e-14);check("analytical tangent finite difference",norm((1/2e-5)*(exact(1.,probe+1e-5*Vec<2>{.3,-.2})-exact(1.,probe-1e-5*Vec<2>{.3,-.2}))-mv(exact_jacobian(1.,probe),Vec<2>{.3,-.2})),1e-10);
 auto derivative=(1/2e-5)*(exact(1.+1e-5,truth)-exact(1.-1e-5,truth));auto point=exact(1.,truth);check("analytical thermal solution satisfies heat ODE",std::abs(derivative[2]-(beta*point[1]*point[1]-decay*point[2])),2e-10);check("analytical electrical energy dissipation",std::abs((energy(exact(1.+1e-5,truth))-energy(exact(1.-1e-5,truth)))/2e-5+R*point[1]*point[1]),2e-10);
 constexpr std::size_t quantities=13;std::array<const char*,quantities> names{"electrical_state","temperature_state","tangent","observation_adjoint","observation_cost","observation_gradient","observation_hessian","initial_control","running_cost","running_gradient","running_costate","running_hessian","fitted_energy"};
 std::ofstream convergence(out/"convergence.csv"),orders(out/"orders.csv"),fits(out/"fits.csv");convergence<<std::setprecision(17)<<"design,theta,steps,h_s";for(auto name:names)convergence<<','<<name;convergence<<'\n';orders<<std::setprecision(17)<<"design,theta,quantity,order\n";fits<<std::setprecision(17)<<"design,theta,steps,v0,i0,analytical_v0,analytical_i0\n";
 for(int design:{0,1})for(double theta:{.5,.65}){auto reference=analytical_fit({1.1,.6},design);std::array<double,quantities> previous{},errors{};for(std::size_t steps:{32u,64u,128u,256u,512u,1024u}){auto sys=system(steps,theta,design);auto ev=sys.evaluate(probe);auto optimum=fit(sys,{1.1,.6});auto exactcost=reference_cost(probe,design);auto H=hessian(sys,probe);auto run=system(steps,theta,0,true);auto re=run.evaluate(probe);auto costates=run.cost_to_go_adjoint(probe,re);auto D=dissipated_matrix(horizon);auto Q=scaled(2.,D);auto tangent=sys.tangent(probe,ev.trajectory,{.3,-.2});
  check("inverse stationarity",norm(sys.evaluate(optimum.control).gradient),1e-7);check("forward Newton residual",ev.trajectory.max_residual,2e-12);check("Hessian symmetry",std::abs(H[0][1]-H[1][0]),2e-9);check("nonlinear residual curvature differs from Gauss Newton",matrix_error(exactcost.hessian,exactcost.gauss_newton)>1.?0.:1.,0.);
  double ee=0.,te=0.,se=0.,le=0.,ls=0.,ce=0.,cs=0.,balance=0.,thermal_balance=0.,symmetry=0.;auto opposite=sys.forward(-1.*probe);
  for(std::size_t n=0;n<=steps;++n){double tau=sys.grid().time[n]-t0;auto x=exact(tau,probe),la=nodal_costate(tau,probe,design),lc=running_costate(tau,probe);auto xn=ev.trajectory.state[n];ee=std::max(ee,std::max(std::abs(xn[0]-x[0]),std::abs(xn[1]-x[1])));te=std::max(te,std::abs(xn[2]-x[2]));se=std::max(se,norm(tangent[n]-mv(exact_jacobian(tau,probe),Vec<2>{.3,-.2})));le=std::max(le,norm(ev.nodal_adjoint[n]-la));ls=std::max(ls,norm(la));ce=std::max(ce,norm(costates[n]-lc));cs=std::max(cs,norm(lc));symmetry=std::max(symmetry,norm(opposite.state[n]-Vec<3>{-xn[0],-xn[1],xn[2]}));if(n){auto old=ev.trajectory.state[n-1],delta=xn-old,mid=(1-theta)*old+theta*xn;double h=sys.grid().time[n]-sys.grid().time[n-1];balance=std::max(balance,std::abs(energy(xn)-energy(old)+h*R*mid[1]*mid[1]-(.5-theta)*(C*delta[0]*delta[0]+L*delta[1]*delta[1])));thermal_balance=std::max(thermal_balance,std::abs(heat_capacity*delta[2]+h*cooling*mid[2]-h*R*((1-theta)*old[1]*old[1]+theta*xn[1]*xn[1])));}}
  check("discrete electrothermal sign symmetry",symmetry,2e-12);check("independent theta electrical energy identity",balance,1e-13);check("theta resistor thermal balance",thermal_balance,1e-12);check("terminal observation adjoint zero",norm(ev.nodal_adjoint.back()),1e-15);check("terminal running costate zero",norm(costates.back()),1e-15);
  previous=errors;double jr=dot(probe,mv(D,probe));auto gr=mv(Q,probe);errors={ee,te,se,le/ls,std::abs(ev.cost-exactcost.cost)/exactcost.cost,norm(ev.gradient-exactcost.gradient)/norm(exactcost.gradient),matrix_error(H,exactcost.hessian)/std::max(norm(exactcost.hessian[0]),norm(exactcost.hessian[1])),norm(optimum.control-reference),std::abs(re.cost-jr)/jr,norm(re.gradient-gr)/norm(gr),ce/cs,matrix_error(hessian(run,probe),Q)/std::max(norm(Q[0]),norm(Q[1])),std::abs(energy(Vec<3>{optimum.control[0],optimum.control[1],0.})-energy(Vec<3>{reference[0],reference[1],0.}))};
  convergence<<design<<','<<theta<<','<<steps<<','<<horizon/steps;for(double e:errors)convergence<<','<<e;convergence<<'\n';fits<<design<<','<<theta<<','<<steps<<','<<optimum.control[0]<<','<<optimum.control[1]<<','<<reference[0]<<','<<reference[1]<<'\n';
  if(steps==128&&theta==.5){Vec<2> d{.3,-.2};double eps=1e-4;auto ep=sys.evaluate(probe+eps*d),em=sys.evaluate(probe-eps*d);check("adjoint cost finite difference",std::abs((ep.cost-em.cost)/(2*eps)-dot(ev.gradient,d)),3e-5);check("incremental adjoint gradient finite difference",norm((1/(2*eps))*(ep.gradient-em.gradient)-sys.hessian_vector(probe,d)),3e-5);double paired=0.;for(auto o:observations(design)){auto n=node_at(sys.grid(),o.tau);paired+=(ev.trajectory.state[n][o.component]-o.value)*tangent[n][o.component]/(o.scale*o.scale);}check("tangent adjoint duality",std::abs(paired-dot(ev.gradient,d)),1e-9);
   if(design==0){std::ofstream costate(out/"costates.csv");costate<<std::setprecision(17)<<"elapsed_s,discrete_v,discrete_i,analytical_v,analytical_i\n";for(std::size_t n=0;n<costates.size();++n){double tau=sys.grid().time[n]-t0;auto l=running_costate(tau,probe);costate<<tau<<','<<costates[n][0]<<','<<costates[n][1]<<','<<l[0]<<','<<l[1]<<'\n';}}
  }
 }
 for(std::size_t j=0;j<quantities;++j){double order=std::log2(previous[j]/errors[j]);orders<<design<<','<<theta<<','<<names[j]<<','<<order<<'\n';check(std::string("temporal convergence ")+names[j],std::abs(order-(theta==.5?2.:1.)),theta==.5?.08:.2);}
 }
 auto base=system(1024,.5);auto positive=fit(base,{1.1,.6}),negative=fit(base,{-1.1,-.6});check("two discrete optimized polarities",norm(positive.control+negative.control),2e-9);check("two discrete equal optimized costs",std::abs(base.evaluate(positive.control).cost-base.evaluate(negative.control).cost),2e-10);for(auto x:std::array<Vec<2>,2>{positive.control,negative.control})check("full rank local Hessian despite global ambiguity",std::abs(static_cast<double>(psd_spectrum_2d(hessian(base,x)).rank)-2.),0.);
 std::ofstream branch_fits(out/"branch_fits.csv");branch_fits<<std::setprecision(17)<<"design,seed_sign,v0,i0,cost,gradient_norm,local_rank,smallest_hessian_eigenvalue\n";for(int design:{0,1,2})for(int sign:{1,-1}){if(design==1&&sign<0)continue;auto sys=system(1024,.5,design);auto result=fit(sys,static_cast<double>(sign)*Vec<2>{1.1,.6});auto ev=sys.evaluate(result.control);auto spectrum=psd_spectrum_2d(hessian(sys,result.control));branch_fits<<design<<','<<sign<<','<<result.control[0]<<','<<result.control[1]<<','<<ev.cost<<','<<norm(ev.gradient)<<','<<spectrum.rank<<','<<spectrum.eigenvalues[1]<<'\n';check("reoptimized branch is a full-rank stationary local minimum",spectrum.rank==2&&norm(ev.gradient)<=1e-7?0.:1.,0.);}
 std::ofstream trajectories(out/"trajectories.csv"),observations_csv(out/"observations.csv"),traces(out/"optimizer_trace.csv");trajectories<<std::setprecision(17)<<"branch,elapsed_s,true_v,true_i,true_temperature_C,true_energy,analytical_v,analytical_i,analytical_temperature_C,discrete_v,discrete_i,discrete_temperature_C,discrete_energy\n";observations_csv<<std::setprecision(17)<<"design,elapsed_s,component,value,scale\n";traces<<std::setprecision(17)<<"branch,iteration,v0,i0,cost,gradient_norm\n";
 for(int design:{0,1,2})for(auto o:observations(design))observations_csv<<design<<','<<o.tau<<','<<o.component<<','<<o.value<<','<<o.scale<<'\n';
 for(int sign:{1,-1}){auto sys=system(128,.5);auto result=fit(sys,static_cast<double>(sign)*Vec<2>{1.1,.6});auto tr=sys.forward(result.control);auto ref=analytical_fit(static_cast<double>(sign)*Vec<2>{1.1,.6});for(std::size_t n=0;n<tr.state.size();++n){double tau=sys.grid().time[n]-t0;auto x=exact(tau,truth),a=exact(tau,ref),d=tr.state[n];trajectories<<sign<<','<<tau<<','<<x[0]<<','<<x[1]<<','<<ambient+x[2]<<','<<energy(x)<<','<<a[0]<<','<<a[1]<<','<<ambient+a[2]<<','<<d[0]<<','<<d[1]<<','<<ambient+d[2]<<','<<energy(d)<<'\n';}for(std::size_t j=0;j<result.trace.size();++j){auto it=result.trace[j];traces<<sign<<','<<j<<','<<it.control[0]<<','<<it.control[1]<<','<<it.cost<<','<<it.gradient_norm<<'\n';}}
 namespace q=electrothermal::qualification;std::ofstream decisions(out/"qualification_decisions.csv"),envelopes(out/"qualification_envelopes.csv"),boxes(out/"feasible_boxes.csv"),branches(out/"branch_summary.csv");decisions<<std::setprecision(17)<<"case,goal,units,tolerance,qualified,persistent_s,local_only_s,joint_qualified,joint_s\n";envelopes<<std::setprecision(17)<<"case,elapsed_s,end_s,goal,tolerance,global_bound,selected_branch_bound,electrical_allowance,thermal_allowance\n";boxes<<std::setprecision(17)<<"case,set,lo_v,lo_i,hi_v,hi_i\n";branches<<std::setprecision(17)<<"case,positive_boxes,negative_boxes,unresolved_boxes,visited,resolution_complete\n";
 std::cout<<"\nELECTROTHERMAL ENGINEERING QUALIFICATION\nAll retained feasible components; bounded sensor errors; retrospective whole intervals through 8 seconds.\n";
 for(int design:{0,1,2}){std::string name=design==0?"temperature_only":design==1?"signed_voltage":"weak_signed_voltage";auto sys=system(1024,.5,design);auto r=q::experiment(sys,design,[&](auto key,double error,double tol){check(name+": "+key,error,tol);});branches<<name<<','<<r.positive<<','<<r.negative<<','<<r.unresolved<<','<<r.cover.visited<<','<<r.cover.resolution_complete<<'\n';report(name+"_positive_boxes",r.positive);report(name+"_negative_boxes",r.negative);
  for(int goal=0;goal<4;++goal){decisions<<name<<','<<q::names[goal]<<','<<q::units[goal]<<','<<q::tolerances[goal]<<','<<static_cast<bool>(r.decision.persistent[goal])<<',';optional(decisions,r.decision.persistent[goal]);decisions<<',';optional(decisions,r.local_decision.persistent[goal]);decisions<<','<<static_cast<bool>(r.decision.joint)<<',';optional(decisions,r.decision.joint);decisions<<'\n';std::cout<<name<<" / "<<q::names[goal]<<": ";if(r.decision.persistent[goal])std::cout<<"QUALIFIED from "<<*r.decision.persistent[goal]<<" s\n";else std::cout<<"NOT QUALIFIED\n";}
  for(int goal=0;goal<4;++goal){bool expected=design==1||goal>=2;check(name+" expected physical goal verdict",static_cast<bool>(r.decision.persistent[goal])==expected?0.:1.,0.);if(goal>=2)check(name+" sign-invariant goal qualifies from start",r.decision.persistent[goal].value_or(-1.),0.);if(design!=1&&goal<2)check(name+" selected branch alone would incorrectly qualify",r.local_decision.persistent[goal]?0.:1.,0.);}check(name+" expected joint engineering verdict",static_cast<bool>(r.decision.joint)==(design==1)?0.:1.,0.);
  std::cout<<name<<" / ALL GOALS: ";if(r.decision.joint)std::cout<<"QUALIFIED from "<<*r.decision.joint<<" s\n";else std::cout<<"NOT QUALIFIED\n";
  for(std::size_t j=0;j<sys.grid().steps();++j)for(int goal=0;goal<4;++goal)envelopes<<name<<','<<sys.grid().time[j]-t0<<','<<sys.grid().time[j+1]-t0<<','<<q::names[goal]<<','<<q::tolerances[goal]<<','<<r.whole[j][goal]<<','<<r.local[j][goal]<<','<<r.error.electrical[j+1]<<','<<r.error.thermal[j+1]<<'\n';
  for(bool exact_set:{false,true})for(auto b:(exact_set?r.reference:r.cover).boxes)boxes<<name<<','<<(exact_set?"analytical":"numerical_outer")<<','<<b.lower[0]<<','<<b.lower[1]<<','<<b.upper[0]<<','<<b.upper[1]<<'\n';
  check(name+" retained positive branch",r.positive>0?0.:1.,0.);check(name+" negative branch matches measurement sufficiency",(design==1?r.negative==0:r.negative>0)?0.:1.,0.);
 }
 report("checks_passed",static_cast<double>(check.count));std::cout<<"Electrothermal validation PASS; physical decisions are separate from solver convergence.\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
